[metadata] {"type": "create", "filePath": "/app/output/styles.css", "content": "/* ========================================
   LearnForge — Design System & Custom Styles
   ======================================== */

/* --- CSS Variables --- */
:root {
  --primary-50: #eef2ff;
  --primary-100: #e0e7ff;
  --primary-200: #c7d2fe;
  --primary-300: #a5b4fc;
  --primary-400: #818cf8;
  --primary-500: #6366f1;
  --primary-600: #4f46e5;
  --primary-700: #4338ca;
  --primary-800: #3730a3;
  --primary-900: #312e81;
  --primary-950: #1e1b4b;

  --accent-400: #fb923c;
  --accent-500: #f97316;
  --accent-600: #ea580c;

  --coral-400: #ff8a8a;
  --coral-500: #ff6b6b;
  --coral-600: #ef4444;

  --surface-white: #ffffff;
  --surface-50: #f8fafc;
  --surface-100: #f1f5f9;
  --surface-200: #e2e8f0;

  --text-primary: #1e1b4b;
  --text-secondary: #475569;
  --text-muted: #94a3b8;

  --shadow-sm: 0 1px 2px 0 rgb(0 0 0 / 0.05);
  --shadow-md: 0 4px 6px -1px rgb(0 0 0 / 0.07), 0 2px 4px -2px rgb(0 0 0 / 0.05);
  --shadow-lg: 0 10px 15px -3px rgb(0 0 0 / 0.08), 0 4px 6px -4px rgb(0 0 0 / 0.04);
  --shadow-xl: 0 20px 25px -5px rgb(0 0 0 / 0.08), 0 8px 10px -6px rgb(0 0 0 / 0.04);

  --radius-sm: 0.5rem;
  --radius-md: 0.75rem;
  --radius-lg: 1rem;
  --radius-xl: 1.25rem;
  --radius-2xl: 1.5rem;
  --radius-full: 9999px;
}

/* --- Base Styles --- */
*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
  color: var(--text-primary);
  background: var(--surface-white);
  line-height: 1.6;
  overflow-x: hidden;
}

/* --- Typography --- */
h1, h2, h3, h4, h5, h6 {
  font-weight: 800;
  line-height: 1.1;
  letter-spacing: -0.025em;
  color: var(--text-primary);
}

/* --- Animations --- */
@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(30px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes slideInLeft {
  from {
    opacity: 0;
    transform: translateX(-40px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes slideInRight {
  from {
    opacity: 0;
    transform: translateX(40px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes scaleIn {
  from {
    opacity: 0;
    transform: scale(0.9);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

@keyframes float {
  0%, 100% { transform: translateY(0); }
  50% { transform: translateY(-10px); }
}

@keyframes pulse-glow {
  0%, 100% { box-shadow: 0 0 0 0 rgba(79, 70, 229, 0.4); }
  50% { box-shadow: 0 0 0 12px rgba(79, 70, 229, 0); }
}

@keyframes countUp {
  from { opacity: 0; transform: translateY(20px); }
  to { opacity: 1; transform: translateY(0); }
}

@keyframes shimmer {
  0% { background-position: -200% 0; }
  100% { background-position: 200% 0; }
}

/* --- Scroll Animation Classes --- */
.animate-on-scroll {
  opacity: 0;
  transform: translateY(30px);
  transition: opacity 0.7s ease-out, transform 0.7s ease-out;
}

.animate-on-scroll.visible {
  opacity: 1;
  transform: translateY(0);
}

.animate-on-scroll.delay-1 { transition-delay: 0.1s; }
.animate-on-scroll.delay-2 { transition-delay: 0.2s; }
.animate-on-scroll.delay-3 { transition-delay: 0.3s; }
.animate-on-scroll.delay-4 { transition-delay: 0.4s; }
.animate-on-scroll.delay-5 { transition-delay: 0.5s; }

/* --- Hero Section --- */
.hero-gradient {
  background: linear-gradient(135deg, #eef2ff 0%, #e0e7ff 30%, #f8fafc 60%, #fff7ed 100%);
  position: relative;
  overflow: hidden;
}

.hero-gradient::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -30%;
  width: 80%;
  height: 120%;
  background: radial-gradient(ellipse, rgba(79, 70, 229, 0.08) 0%, transparent 70%);
  pointer-events: none;
}

.hero-gradient::after {
  content: '';
  position: absolute;
  bottom: -30%;
  left: -20%;
  width: 60%;
  height: 80%;
  background: radial-gradient(ellipse, rgba(249, 115, 22, 0.06) 0%, transparent 70%);
  pointer-events: none;
}

/* --- Product Cards --- */
.product-card {
  background: var(--surface-white);
  border: 1px solid var(--surface-200);
  border-radius: var(--radius-xl);
  padding: 2rem;
  transition: all 0.3s ease;
  position: relative;
  overflow: hidden;
}

.product-card::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 4px;
  background: linear-gradient(90deg, var(--primary-500), var(--accent-500));
  transform: scaleX(0);
  transition: transform 0.3s ease;
  transform-origin: left;
}

.product-card:hover {
  border-color: var(--primary-200);
  box-shadow: var(--shadow-xl);
  transform: translateY(-4px);
}

.product-card:hover::before {
  transform: scaleX(1);
}

/* --- Feature Card --- */
.feature-card {
  background: var(--surface-white);
  border: 1px solid var(--surface-200);
  border-radius: var(--radius-lg);
  padding: 1.75rem;
  transition: all 0.3s ease;
}

.feature-card:hover {
  border-color: var(--primary-200);
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

/* --- Stats Bar --- */
.stats-bar {
  background: var(--primary-950);
  position: relative;
  overflow: hidden;
}

.stats-bar::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(79, 70, 229, 0.3) 0%, transparent 50%, rgba(249, 115, 22, 0.15) 100%);
  pointer-events: none;
}

/* --- Tab Component --- */
.tab-btn {
  padding: 0.75rem 1.5rem;
  font-weight: 600;
  font-size: 0.9375rem;
  border-radius: var(--radius-full);
  transition: all 0.25s ease;
  cursor: pointer;
  border: none;
  background: transparent;
  color: var(--text-secondary);
  white-space: nowrap;
}

.tab-btn:hover {
  color: var(--primary-700);
  background: var(--primary-50);
}

.tab-btn.active {
  background: var(--primary-600);
  color: white;
  box-shadow: 0 2px 8px rgba(79, 70, 229, 0.3);
}

/* --- Hero View Tabs (Creator/Student) --- */
.view-tab {
  padding: 0.625rem 1.5rem;
  font-weight: 600;
  font-size: 0.875rem;
  cursor: pointer;
  border: 2px solid var(--surface-200);
  background: var(--surface-white);
  color: var(--text-secondary);
  transition: all 0.25s ease;
}

.view-tab:first-child {
  border-radius: var(--radius-md) 0 0 var(--radius-md);
}

.view-tab:last-child {
  border-radius: 0 var(--radius-md) var(--radius-md) 0;
  border-left: none;
}

.view-tab.active {
  background: var(--primary-600);
  color: white;
  border-color: var(--primary-600);
}

.view-tab:not(.active):hover {
  border-color: var(--primary-300);
  color: var(--primary-700);
}

/* --- Preview Panel --- */
.preview-panel {
  background: var(--surface-white);
  border: 1px solid var(--surface-200);
  border-radius: var(--radius-xl);
  box-shadow: var(--shadow-xl);
  overflow: hidden;
  min-height: 340px;
  position: relative;
}

.preview-panel .preview-content {
  animation: fadeIn 0.4s ease;
}

/* --- FAQ Accordion --- */
.faq-item {
  border: 1px solid var(--surface-200);
  border-radius: var(--radius-lg);
  overflow: hidden;
  transition: all 0.3s ease;
  background: var(--surface-white);
}

.faq-item:hover {
  border-color: var(--primary-200);
}

.faq-item.open {
  border-color: var(--primary-300);
  box-shadow: var(--shadow-md);
}

.faq-question {
  display: flex;
  align-items: center;
  justify-content: space-between;
  width: 100%;
  padding: 1.25rem 1.5rem;
  background: none;
  border: none;
  cursor: pointer;
  text-align: left;
  font-weight: 600;
  font-size: 1rem;
  color: var(--text-primary);
  font-family: inherit;
  gap: 1rem;
  transition: color 0.2s ease;
}

.faq-question:hover {
  color: var(--primary-700);
}

.faq-icon {
  width: 24px;
  height: 24px;
  border-radius: 50%;
  background: var(--primary-50);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: all 0.3s ease;
  color: var(--primary-600);
}

.faq-item.open .faq-icon {
  background: var(--primary-600);
  color: white;
  transform: rotate(45deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.35s ease, padding 0.35s ease;
}

.faq-item.open .faq-answer {
  max-height: 300px;
}

.faq-answer-inner {
  padding: 0 1.5rem 1.25rem;
  color: var(--text-secondary);
  line-height: 1.7;
}

/* --- Testimonial Carousel --- */
.testimonial-carousel {
  position: relative;
  overflow: hidden;
}

.testimonial-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.4, 0, 0.2, 1);
}

.testimonial-card {
  background: var(--surface-white);
  border: 1px solid var(--surface-200);
  border-radius: var(--radius-xl);
  padding: 2rem;
  min-width: 100%;
  flex-shrink: 0;
}

@media (min-width: 768px) {
  .testimonial-card {
    min-width: 50%;
  }
}

@media (min-width: 1024px) {
  .testimonial-card {
    min-width: 33.333%;
  }
}

.carousel-btn {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  background: var(--surface-white);
  border: 1px solid var(--surface-200);
  display: flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  transition: all 0.25s ease;
  color: var(--text-secondary);
  box-shadow: var(--shadow-md);
}

.carousel-btn:hover {
  background: var(--primary-600);
  color: white;
  border-color: var(--primary-600);
}

.carousel-dots {
  display: flex;
  gap: 0.5rem;
  justify-content: center;
  margin-top: 1.5rem;
}

.carousel-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--surface-200);
  border: none;
  cursor: pointer;
  transition: all 0.25s ease;
  padding: 0;
}

.carousel-dot.active {
  background: var(--primary-600);
  width: 24px;
  border-radius: 4px;
}

/* --- Pricing Cards --- */
.pricing-card {
  background: var(--surface-white);
  border: 2px solid var(--surface-200);
  border-radius: var(--radius-xl);
  padding: 2rem;
  transition: all 0.3s ease;
  position: relative;
}

.pricing-card:hover {
  border-color: var(--primary-200);
  box-shadow: var(--shadow-xl);
}

.pricing-card.featured {
  border-color: var(--primary-500);
  box-shadow: 0 0 0 1px var(--primary-500), var(--shadow-xl);
  transform: scale(1.03);
}

.pricing-card.featured::before {
  content: 'Most Popular';
  position: absolute;
  top: -14px;
  left: 50%;
  transform: translateX(-50%);
  background: linear-gradient(135deg, var(--primary-600), var(--accent-500));
  color: white;
  padding: 0.375rem 1.25rem;
  border-radius: var(--radius-full);
  font-size: 0.8125rem;
  font-weight: 700;
  letter-spacing: 0.02em;
}

/* --- Integration Logo Grid --- */
.integration-logo {
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 1.25rem;
  background: var(--surface-50);
  border: 1px solid var(--surface-200);
  border-radius: var(--radius-lg);
  font-weight: 600;
  font-size: 0.8125rem;
  color: var(--text-secondary);
  transition: all 0.25s ease;
  min-height: 72px;
}

.integration-logo:hover {
  border-color: var(--primary-200);
  background: var(--surface-white);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}

/* --- CTA Banner --- */
.cta-banner {
  background: linear-gradient(135deg, var(--primary-900) 0%, var(--primary-700) 50%, var(--primary-800) 100%);
  position: relative;
  overflow: hidden;
}

.cta-banner::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 60%;
  height: 150%;
  background: radial-gradient(ellipse, rgba(249, 115, 22, 0.15) 0%, transparent 60%);
  pointer-events: none;
}

.cta-banner::after {
  content: '';
  position: absolute;
  bottom: -40%;
  left: -10%;
  width: 40%;
  height: 100%;
  background: radial-gradient(ellipse, rgba(99, 102, 241, 0.2) 0%, transparent 60%);
  pointer-events: none;
}

/* --- Mobile Nav --- */
.mobile-nav {
  position: fixed;
  inset: 0;
  background: rgba(30, 27, 75, 0.5);
  backdrop-filter: blur(4px);
  z-index: 50;
  opacity: 0;
  visibility: hidden;
  transition: all 0.3s ease;
}

.mobile-nav.open {
  opacity: 1;
  visibility: visible;
}

.mobile-nav-panel {
  position: absolute;
  top: 0;
  right: 0;
  width: min(320px, 85vw);
  height: 100%;
  background: var(--surface-white);
  padding: 2rem;
  transform: translateX(100%);
  transition: transform 0.3s cubic-bezier(0.4, 0, 0.2, 1);
  overflow-y: auto;
}

.mobile-nav.open .mobile-nav-panel {
  transform: translateX(0);
}

/* --- Step Indicator --- */
.step-number {
  width: 48px;
  height: 48px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--primary-500), var(--primary-700));
  color: white;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 800;
  font-size: 1.25rem;
  flex-shrink: 0;
}

.step-connector {
  width: 2px;
  height: 40px;
  background: linear-gradient(to bottom, var(--primary-300), var(--primary-100));
  margin-left: 23px;
}

/* --- Badge --- */
.badge {
  display: inline-flex;
  align-items: center;
  padding: 0.375rem 1rem;
  border-radius: var(--radius-full);
  font-size: 0.8125rem;
  font-weight: 600;
  letter-spacing: 0.02em;
}

.badge-primary {
  background: var(--primary-50);
  color: var(--primary-700);
  border: 1px solid var(--primary-200);
}

.badge-accent {
  background: rgba(249, 115, 22, 0.1);
  color: var(--accent-600);
  border: 1px solid rgba(249, 115, 22, 0.2);
}

/* --- Nav --- */
.nav-fixed {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 40;
  background: rgba(255, 255, 255, 0.92);
  backdrop-filter: blur(12px);
  border-bottom: 1px solid transparent;
  transition: all 0.3s ease;
}

.nav-fixed.scrolled {
  border-bottom-color: var(--surface-200);
  box-shadow: var(--shadow-sm);
}

/* --- Decorative Elements --- */
.dot-pattern {
  background-image: radial-gradient(circle, var(--primary-200) 1px, transparent 1px);
  background-size: 24px 24px;
}

.gradient-text {
  background: linear-gradient(135deg, var(--primary-600), var(--accent-500));
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.glass-card {
  background: rgba(255, 255, 255, 0.7);
  backdrop-filter: blur(12px);
  border: 1px solid rgba(255, 255, 255, 0.5);
}

/* --- Button Styles --- */
.btn-primary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.875rem 2rem;
  background: var(--primary-600);
  color: white;
  font-weight: 700;
  font-size: 0.9375rem;
  border-radius: var(--radius-md);
  border: none;
  cursor: pointer;
  transition: all 0.25s ease;
  text-decoration: none;
  font-family: inherit;
}

.btn-primary:hover {
  background: var(--primary-700);
  box-shadow: 0 4px 14px rgba(79, 70, 229, 0.35);
  transform: translateY(-1px);
}

.btn-secondary {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.875rem 2rem;
  background: transparent;
  color: var(--primary-700);
  font-weight: 700;
  font-size: 0.9375rem;
  border-radius: var(--radius-md);
  border: 2px solid var(--primary-200);
  cursor: pointer;
  transition: all 0.25s ease;
  text-decoration: none;
  font-family: inherit;
}

.btn-secondary:hover {
  border-color: var(--primary-500);
  background: var(--primary-50);
}

.btn-accent {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.875rem 2rem;
  background: var(--accent-500);
  color: white;
  font-weight: 700;
  font-size: 0.9375rem;
  border-radius: var(--radius-md);
  border: none;
  cursor: pointer;
  transition: all 0.25s ease;
  text-decoration: none;
  font-family: inherit;
}

.btn-accent:hover {
  background: var(--accent-600);
  box-shadow: 0 4px 14px rgba(249, 115, 22, 0.35);
  transform: translateY(-1px);
}

/* --- Responsive --- */
@media (max-width: 768px) {
  .hero-gradient {
    padding-top: 7rem;
    padding-bottom: 3rem;
  }

  .preview-panel {
    min-height: 260px;
  }

  .pricing-card.featured {
    transform: none;
  }

  .stats-bar .stat-item {
    padding: 1rem 0;
  }
}

@media (max-width: 480px) {
  .product-card {
    padding: 1.5rem;
  }

  .testimonial-card {
    padding: 1.5rem;
  }

  .faq-question {
    padding: 1rem 1.25rem;
    font-size: 0.9375rem;
  }

  .faq-answer-inner {
    padding: 0 1.25rem 1rem;
    font-size: 0.9375rem;
  }
}

/* --- Section Alternating --- */
.section-alt {
  background: var(--surface-50);
}

/* --- Icon Containers --- */
.icon-container {
  width: 56px;
  height: 56px;
  border-radius: var(--radius-lg);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
}

.icon-container-primary {
  background: var(--primary-50);
  color: var(--primary-600);
}

.icon-container-accent {
  background: rgba(249, 115, 22, 0.1);
  color: var(--accent-600);
}

.icon-container-coral {
  background: rgba(255, 107, 107, 0.1);
  color: var(--coral-500);
}

/* --- Resource Card --- */
.resource-card {
  background: var(--surface-white);
  border: 1px solid var(--surface-200);
  border-radius: var(--radius-lg);
  padding: 1.5rem;
  transition: all 0.3s ease;
  cursor: pointer;
}

.resource-card:hover {
  border-color: var(--primary-200);
  box-shadow: var(--shadow-lg);
  transform: translateY(-2px);
}

/* --- File Type Tag --- */
.file-type-tag {
  display: inline-flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.75rem 1.25rem;
  background: var(--surface-50);
  border: 1px solid var(--surface-200);
  border-radius: var(--radius-md);
  font-weight: 600;
  font-size: 0.875rem;
  color: var(--text-secondary);
  transition: all 0.25s ease;
}

.file-type-tag:hover {
  border-color: var(--primary-200);
  background: var(--surface-white);
  color: var(--primary-700);
}

/* --- Footer --- */
.footer {
  background: var(--primary-950);
  color: rgba(255, 255, 255, 0.7);
}

.footer a {
  color: rgba(255, 255, 255, 0.7);
  text-decoration: none;
  transition: color 0.2s ease;
}

.footer a:hover {
  color: white;
}

.footer-heading {
  color: white;
  font-weight: 700;
  font-size: 0.875rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 1.25rem;
}

/* --- Spotlight Card --- */
.spotlight-card {
  background: var(--surface-white);
  border: 1px solid var(--surface-200);
  border-radius: var(--radius-xl);
  padding: 2rem;
  transition: all 0.3s ease;
}

.spotlight-card:hover {
  border-color: var(--primary-200);
  box-shadow: var(--shadow-xl);
  transform: translateY(-4px);
}

/* --- Tools Grid Item --- */
.tool-item {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  padding: 0.75rem 1rem;
  background: var(--surface-50);
  border: 1px solid var(--surface-200);
  border-radius: var(--radius-md);
  font-size: 0.9375rem;
  font-weight: 500;
  color: var(--text-secondary);
  transition: all 0.25s ease;
}

.tool-item:hover {
  border-color: var(--primary-200);
  background: var(--surface-white);
  color: var(--primary-700);
}

/* --- Scrollbar --- */
::-webkit-scrollbar {
  width: 8px;
}

::-webkit-scrollbar-track {
  background: var(--surface-100);
}

::-webkit-scrollbar-thumb {
  background: var(--primary-200);
  border-radius: 4px;
}

::-webkit-scrollbar-thumb:hover {
  background: var(--primary-300);
}
